INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-0000000000de', 'Place & Travel', 'Grand Rapids, Michigan', 'Born and raised in Grand Rapids; moved to Washington D.C. as congressman.', 'range', 1913, 1948, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000de', 'Place & Travel', 'Washington D.C.', 'Served in Congress and later as VP and President in Washington D.C.', 'range', 1949, 1977, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000de', 'Place & Travel', 'Rancho Mirage, California', 'Retired to Rancho Mirage, California after the presidency.', 'range', 1977, 2006, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000de', 'Work & Education', 'University of Michigan', 'Played college football at University of Michigan; graduated 1935.', 'range', 1931, 1935, '#10b981'),
  ('a0000000-0000-0000-0000-0000000000de', 'Work & Education', 'US Navy — WWII', 'Served in the Pacific during WWII, rising to lieutenant commander.', 'range', 1942, 1946, '#10b981'),
  ('a0000000-0000-0000-0000-0000000000de', 'Work & Education', 'US Congressman', 'Represented Michigan''s 5th district in the House of Representatives.', 'range', 1949, 1973, '#10b981'),
  ('a0000000-0000-0000-0000-0000000000de', 'Work & Education', '38th President of the United States', 'Succeeded Nixon after his resignation; served 1974–1977.', 'range', 1974, 1977, '#10b981'),
  ('a0000000-0000-0000-0000-0000000000de', 'Relations & Family', 'Married Betty Ford', 'Married Elizabeth "Betty" Bloomer in 1948; she became a prominent health advocate.', 'point', 1948, null, '#ec4899'),
  ('a0000000-0000-0000-0000-0000000000de', 'Activities', 'Pardoned Nixon', 'Granted Nixon a full pardon one month after taking office; destroyed his public approval.', 'point', 1974, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-0000000000de', 'Health', 'Death — age 93', 'Died on December 26, 2006 in Rancho Mirage; longest-lived US president at the time.', 'point', 2006, null, '#ef4444');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-0000000000df', 'Place & Travel', 'Yorba Linda, California', 'Born in Yorba Linda; grew up in modest circumstances in Southern California.', 'range', 1913, 1934, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000df', 'Place & Travel', 'Washington D.C.', 'Lived in Washington as congressman, senator, VP, and President.', 'range', 1947, 1974, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000df', 'Place & Travel', 'Park Ridge, New Jersey / New York', 'Retired to New Jersey then New York after resignation.', 'range', 1974, 1994, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000df', 'Work & Education', 'Duke University Law School', 'Graduated from Duke Law School; financed education through scholarships.', 'range', 1934, 1937, '#10b981'),
  ('a0000000-0000-0000-0000-0000000000df', 'Work & Education', 'US Navy — WWII', 'Served in the Navy as a lieutenant commander in the South Pacific.', 'range', 1942, 1946, '#10b981'),
  ('a0000000-0000-0000-0000-0000000000df', 'Work & Education', '37th President of the United States', 'Served two terms; opened relations with China and ended Vietnam involvement.', 'range', 1969, 1974, '#10b981'),
  ('a0000000-0000-0000-0000-0000000000df', 'Relations & Family', 'Married Pat Nixon', 'Married Thelma "Pat" Ryan in 1940; she remained loyal through Watergate.', 'point', 1940, null, '#ec4899'),
  ('a0000000-0000-0000-0000-0000000000df', 'Activities', 'Watergate Break-in', 'Nixon administration operatives broke into DNC headquarters; led to his resignation.', 'point', 1972, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-0000000000df', 'Activities', 'Resignation from Presidency', 'Became the only US president to resign, on August 9, 1974.', 'point', 1974, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-0000000000df', 'Activities', 'Nixon visits China', 'Historic 1972 visit to China opened diplomatic relations after 25 years of isolation.', 'point', 1972, null, '#f59e0b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-0000000000e0', 'Place & Travel', 'Stonewall, Texas', 'Born and raised on a ranch near Stonewall, Texas; deeply tied to the Hill Country.', 'range', 1908, 1930, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000e0', 'Place & Travel', 'Washington D.C.', 'Served in Congress, Senate, and the White House in Washington D.C.', 'range', 1937, 1969, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000e0', 'Place & Travel', 'LBJ Ranch, Texas', 'Retired to his beloved Hill Country ranch after the presidency.', 'range', 1969, 1973, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000e0', 'Work & Education', 'Texas State University', 'Attended Southwest Texas State Teachers College; graduated 1930.', 'range', 1927, 1930, '#10b981'),
  ('a0000000-0000-0000-0000-0000000000e0', 'Work & Education', 'US Congressman', 'Represented Texas in the House from 1937; strong New Deal supporter.', 'range', 1937, 1949, '#10b981'),
  ('a0000000-0000-0000-0000-0000000000e0', 'Work & Education', '36th President of the United States', 'Signed Civil Rights Act, Voting Rights Act, and launched Great Society programs.', 'range', 1963, 1969, '#10b981'),
  ('a0000000-0000-0000-0000-0000000000e0', 'Relations & Family', 'Married Lady Bird Johnson', 'Married Claudia "Lady Bird" Taylor in 1934; she championed highway beautification.', 'point', 1934, null, '#ec4899'),
  ('a0000000-0000-0000-0000-0000000000e0', 'Activities', 'Civil Rights Act Signed', 'Signed the landmark Civil Rights Act of 1964 outlawing racial discrimination.', 'point', 1964, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-0000000000e0', 'Activities', 'Gulf of Tonkin Resolution', 'Escalated US involvement in Vietnam following the Gulf of Tonkin incident.', 'point', 1964, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-0000000000e0', 'Health', 'Death — heart attack', 'Died January 22, 1973 at the LBJ Ranch from a heart attack, aged 64.', 'point', 1973, null, '#ef4444');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-0000000000e1', 'Place & Travel', 'Abilene, Kansas', 'Grew up in Abilene, Kansas; formative years in the Midwest.', 'range', 1890, 1911, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000e1', 'Place & Travel', 'Europe — WWII Supreme Commander', 'Based in London and Paris as Supreme Allied Commander during WWII.', 'range', 1942, 1945, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000e1', 'Place & Travel', 'Washington D.C.', 'Served as Army Chief of Staff, NATO commander, and President in Washington.', 'range', 1945, 1961, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000e1', 'Work & Education', 'West Point Military Academy', 'Graduated from West Point in 1915 — the "class the stars fell on."', 'range', 1911, 1915, '#10b981'),
  ('a0000000-0000-0000-0000-0000000000e1', 'Work & Education', 'Supreme Allied Commander — WWII', 'Commanded the Allied Expeditionary Force including D-Day on June 6, 1944.', 'range', 1942, 1945, '#10b981'),
  ('a0000000-0000-0000-0000-0000000000e1', 'Work & Education', '34th President of the United States', 'Served two terms; built the interstate highway system and warned of military-industrial complex.', 'range', 1953, 1961, '#10b981'),
  ('a0000000-0000-0000-0000-0000000000e1', 'Relations & Family', 'Married Mamie Doud', 'Married Mary "Mamie" Geneva Doud in 1916; she was a popular First Lady.', 'point', 1916, null, '#ec4899'),
  ('a0000000-0000-0000-0000-0000000000e1', 'Activities', 'D-Day — Operation Overlord', 'Commanded the largest amphibious assault in history on June 6, 1944.', 'point', 1944, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-0000000000e1', 'Activities', 'NASA Founded', 'Signed the National Aeronautics and Space Act, creating NASA in 1958.', 'point', 1958, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-0000000000e1', 'Health', 'Heart attack while President', 'Suffered a major heart attack in 1955; recovered and continued in office.', 'point', 1955, null, '#ef4444');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-0000000000e2', 'Place & Travel', 'Lamar, Missouri', 'Born in Lamar; grew up in Independence, Missouri — his lifelong home.', 'range', 1884, 1917, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000e2', 'Place & Travel', 'France — WWI', 'Served as artillery officer in France during World War I.', 'range', 1917, 1919, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000e2', 'Place & Travel', 'Washington D.C.', 'Served as senator and Vice President before becoming President in 1945.', 'range', 1935, 1953, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000e2', 'Work & Education', 'US Army — WWI', 'Commanded Battery D, 129th Field Artillery; rose to captain.', 'range', 1917, 1919, '#10b981'),
  ('a0000000-0000-0000-0000-0000000000e2', 'Work & Education', 'US Senator from Missouri', 'Served in the Senate 1935–1944; chaired Truman Committee investigating war spending.', 'range', 1935, 1944, '#10b981'),
  ('a0000000-0000-0000-0000-0000000000e2', 'Work & Education', '33rd President of the United States', 'Ordered atomic bombings, launched Marshall Plan, and entered Korean War.', 'range', 1945, 1953, '#10b981'),
  ('a0000000-0000-0000-0000-0000000000e2', 'Relations & Family', 'Married Bess Wallace', 'Married Elizabeth "Bess" Wallace in 1919 after a long courtship.', 'point', 1919, null, '#ec4899'),
  ('a0000000-0000-0000-0000-0000000000e2', 'Activities', 'Atomic bomb dropped on Japan', 'Ordered atomic bombings of Hiroshima and Nagasaki, ending WWII in the Pacific.', 'point', 1945, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-0000000000e2', 'Activities', 'Marshall Plan', 'Signed the European Recovery Program (Marshall Plan) to rebuild post-war Europe.', 'point', 1948, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-0000000000e2', 'Activities', 'Desegregated US Armed Forces', 'Signed Executive Order 9981 desegregating the US military in 1948.', 'point', 1948, null, '#f59e0b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-0000000000e3', 'Place & Travel', 'Staunton, Virginia', 'Born in Staunton; raised in Virginia and Georgia in a Presbyterian minister''s home.', 'range', 1856, 1875, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000e3', 'Place & Travel', 'Princeton, New Jersey', 'Spent years as a professor and president at Princeton University.', 'range', 1890, 1910, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000e3', 'Place & Travel', 'Washington D.C.', 'Served as US President through WWI and championed the League of Nations.', 'range', 1913, 1921, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000e3', 'Work & Education', 'Johns Hopkins University — PhD', 'Earned his PhD in political science from Johns Hopkins in 1886.', 'range', 1883, 1886, '#10b981'),
  ('a0000000-0000-0000-0000-0000000000e3', 'Work & Education', 'President of Princeton University', 'Served as Princeton''s president 1902–1910, reforming curriculum and campus life.', 'range', 1902, 1910, '#10b981'),
  ('a0000000-0000-0000-0000-0000000000e3', 'Work & Education', '28th President of the United States', 'Led US through WWI; proposed Fourteen Points and the League of Nations.', 'range', 1913, 1921, '#10b981'),
  ('a0000000-0000-0000-0000-0000000000e3', 'Relations & Family', 'Married Ellen Axson', 'Married Ellen Louise Axson in 1885; she died in the White House in 1914.', 'point', 1885, null, '#ec4899'),
  ('a0000000-0000-0000-0000-0000000000e3', 'Activities', 'League of Nations proposal', 'Championed the League of Nations at the Paris Peace Conference in 1919.', 'point', 1919, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-0000000000e3', 'Health', 'Stroke while campaigning', 'Suffered a severe stroke in 1919 while on a national tour advocating for the League of Nations.', 'point', 1919, null, '#ef4444'),
  ('a0000000-0000-0000-0000-0000000000e3', 'Activities', 'Nobel Peace Prize', 'Awarded the Nobel Peace Prize in 1919 for his role in founding the League of Nations.', 'point', 1919, null, '#f59e0b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-0000000000e4', 'Place & Travel', 'New York City', 'Born in Manhattan; sickly child who transformed himself through vigorous outdoor life.', 'range', 1858, 1884, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000e4', 'Place & Travel', 'Badlands, North Dakota', 'Ranched in the Badlands after the death of his wife and mother in 1884.', 'range', 1884, 1886, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000e4', 'Place & Travel', 'Washington D.C.', 'Served as Civil Service Commissioner, Navy Secretary, VP, and President.', 'range', 1889, 1909, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000e4', 'Work & Education', 'Harvard University', 'Graduated from Harvard in 1880; studied natural history and history.', 'range', 1876, 1880, '#10b981'),
  ('a0000000-0000-0000-0000-0000000000e4', 'Work & Education', 'Rough Riders — Spanish-American War', 'Led the 1st US Volunteer Cavalry (Rough Riders) at the Battle of San Juan Hill.', 'range', 1898, 1898, '#10b981'),
  ('a0000000-0000-0000-0000-0000000000e4', 'Work & Education', '26th President of the United States', 'Trust-busted monopolies, conserved 230 million acres, and built the Panama Canal.', 'range', 1901, 1909, '#10b981'),
  ('a0000000-0000-0000-0000-0000000000e4', 'Relations & Family', 'Married Edith Carow', 'Married Edith Kermit Carow in 1886 after the death of his first wife Alice.', 'point', 1886, null, '#ec4899'),
  ('a0000000-0000-0000-0000-0000000000e4', 'Activities', 'Nobel Peace Prize', 'Won Nobel Peace Prize in 1906 for mediating the Treaty of Portsmouth ending Russo-Japanese War.', 'point', 1906, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-0000000000e4', 'Activities', 'Panama Canal — construction begins', 'Oversaw the start of construction of the Panama Canal in 1904.', 'point', 1904, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-0000000000e4', 'Health', 'Assassination attempt survived', 'Shot in the chest during a campaign speech in 1912; finished the speech before seeking treatment.', 'point', 1912, null, '#ef4444');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-0000000000e5', 'Place & Travel', 'Cincinnati, Ohio', 'Born and raised in Cincinnati in a prominent political family.', 'range', 1857, 1878, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000e5', 'Place & Travel', 'Philippines', 'Served as first civilian Governor-General of the Philippines 1900–1903.', 'range', 1900, 1903, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000e5', 'Place & Travel', 'Washington D.C.', 'Served as Secretary of War, President, and Chief Justice in Washington.', 'range', 1904, 1930, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000e5', 'Work & Education', 'Yale University', 'Graduated from Yale in 1878; later studied law at Cincinnati Law School.', 'range', 1874, 1878, '#10b981'),
  ('a0000000-0000-0000-0000-0000000000e5', 'Work & Education', '27th President of the United States', 'Served one term 1909–1913; continued trust-busting and Philippine policy.', 'range', 1909, 1913, '#10b981'),
  ('a0000000-0000-0000-0000-0000000000e5', 'Work & Education', 'Chief Justice of the United States', 'Appointed Chief Justice in 1921 — the only person to hold both President and Chief Justice.', 'range', 1921, 1930, '#10b981'),
  ('a0000000-0000-0000-0000-0000000000e5', 'Relations & Family', 'Married Helen Herron', 'Married Helen "Nellie" Herron in 1886; she was influential in his political career.', 'point', 1886, null, '#ec4899'),
  ('a0000000-0000-0000-0000-0000000000e5', 'Activities', 'Anti-trust lawsuits', 'Filed more anti-trust suits in one term than Roosevelt did in two.', 'range', 1909, 1913, '#f59e0b'),
  ('a0000000-0000-0000-0000-0000000000e5', 'Health', 'Obesity and health struggles', 'Weighed over 330 lbs; famously got stuck in the White House bathtub.', 'range', 1909, 1913, '#ef4444'),
  ('a0000000-0000-0000-0000-0000000000e5', 'Activities', 'Lost 1912 election to Wilson', 'Defeated by Woodrow Wilson after Theodore Roosevelt split the Republican vote.', 'point', 1912, null, '#f59e0b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-0000000000e6', 'Place & Travel', 'Bronx, New York City', 'Born and raised in the Bronx; grew up in a working-class Puerto Rican family.', 'range', 1989, 2010, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000e6', 'Place & Travel', 'Washington D.C.', 'Moved to D.C. after election to the House of Representatives in 2018.', 'range', 2019, 2026, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000e6', 'Work & Education', 'Boston University', 'Graduated from Boston University with a degree in economics and international relations, 2011.', 'range', 2007, 2011, '#10b981'),
  ('a0000000-0000-0000-0000-0000000000e6', 'Work & Education', 'Bartender / Waitress', 'Worked as a bartender in New York City to help support her family while organizing politically.', 'range', 2011, 2018, '#10b981'),
  ('a0000000-0000-0000-0000-0000000000e6', 'Work & Education', 'US Representative — NY-14', 'Youngest woman ever elected to Congress; re-elected multiple times.', 'range', 2019, 2026, '#10b981'),
  ('a0000000-0000-0000-0000-0000000000e6', 'Activities', 'Green New Deal introduced', 'Co-authored the Green New Deal resolution with Senator Ed Markey in 2019.', 'point', 2019, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-0000000000e6', 'Activities', 'Democratic Socialist activism', 'Key figure in the Democratic Socialists of America; pushed for Medicare for All.', 'range', 2018, 2026, '#f59e0b'),
  ('a0000000-0000-0000-0000-0000000000e6', 'Relations & Family', 'Engaged to Riley Roberts', 'Long-term relationship with Riley Roberts; announced engagement in 2022.', 'point', 2022, null, '#ec4899'),
  ('a0000000-0000-0000-0000-0000000000e6', 'Activities', 'January 6 Capitol storming', 'Was in the Capitol during the January 6, 2021 attack; spoke publicly about her fear.', 'point', 2021, null, '#f59e0b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-0000000000e7', 'Place & Travel', 'Brooklyn, New York', 'Born and raised in Brooklyn in a working-class Jewish family.', 'range', 1941, 1959, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000e7', 'Place & Travel', 'Burlington, Vermont', 'Moved to Vermont; served as mayor, congressman, and senator.', 'range', 1968, 2026, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000e7', 'Work & Education', 'University of Chicago', 'Graduated from the University of Chicago with a degree in political science, 1964.', 'range', 1960, 1964, '#10b981'),
  ('a0000000-0000-0000-0000-0000000000e7', 'Work & Education', 'Mayor of Burlington', 'Served as Mayor of Burlington, Vermont 1981–1989.', 'range', 1981, 1989, '#10b981'),
  ('a0000000-0000-0000-0000-0000000000e7', 'Work & Education', 'US Senator from Vermont', 'Longest-serving independent in congressional history; caucuses with Democrats.', 'range', 2007, 2026, '#10b981'),
  ('a0000000-0000-0000-0000-0000000000e7', 'Relations & Family', 'Married Jane O''Meara', 'Married Jane O''Meara in 1988; they have blended family of four children.', 'point', 1988, null, '#ec4899'),
  ('a0000000-0000-0000-0000-0000000000e7', 'Activities', '2016 Presidential Primary Campaign', 'Ran for Democratic nomination; won 22 states against Hillary Clinton.', 'range', 2015, 2016, '#f59e0b'),
  ('a0000000-0000-0000-0000-0000000000e7', 'Activities', '2020 Presidential Primary Campaign', 'Led polls early before dropping out and endorsing Biden in April 2020.', 'range', 2019, 2020, '#f59e0b'),
  ('a0000000-0000-0000-0000-0000000000e7', 'Activities', 'Chair of Senate Budget Committee', 'Chaired the Senate Budget Committee; pushed for the $3.5T reconciliation bill.', 'range', 2021, 2023, '#f59e0b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-0000000000e8', 'Place & Travel', 'Baltimore, Maryland', 'Born and raised in Baltimore in a prominent Italian-American political family.', 'range', 1940, 1962, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000e8', 'Place & Travel', 'San Francisco, California', 'Built her political career in San Francisco; represented the city in Congress.', 'range', 1962, 2026, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000e8', 'Work & Education', 'Trinity College, Washington D.C.', 'Graduated from Trinity College in 1962 with a degree in political science.', 'range', 1958, 1962, '#10b981'),
  ('a0000000-0000-0000-0000-0000000000e8', 'Work & Education', 'US Representative — CA-12', 'Served San Francisco in the House of Representatives from 1987.', 'range', 1987, 2026, '#10b981'),
  ('a0000000-0000-0000-0000-0000000000e8', 'Work & Education', 'Speaker of the House', 'First woman to serve as Speaker; served 2007–2011 and 2019–2023.', 'range', 2007, 2011, '#10b981'),
  ('a0000000-0000-0000-0000-0000000000e8', 'Relations & Family', 'Married Paul Pelosi', 'Married Paul Pelosi in 1963; they have five children.', 'point', 1963, null, '#ec4899'),
  ('a0000000-0000-0000-0000-0000000000e8', 'Activities', 'ACA passed', 'Steered the Affordable Care Act through the House in 2010.', 'point', 2010, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-0000000000e8', 'Activities', 'Trump impeachments', 'Led the House impeachment of Donald Trump in both 2019 and 2021.', 'range', 2019, 2021, '#f59e0b'),
  ('a0000000-0000-0000-0000-0000000000e8', 'Activities', 'Taiwan visit', 'Visited Taiwan in August 2022 despite warnings from China; highest-ranking official to do so in 25 years.', 'point', 2022, null, '#f59e0b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-0000000000e9', 'Place & Travel', 'Sheffield, Alabama', 'Born in Sheffield, Alabama; family moved to Kentucky during his childhood.', 'range', 1942, 1960, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000e9', 'Place & Travel', 'Louisville / Frankfort, Kentucky', 'Built his career in Kentucky state politics before moving to Washington.', 'range', 1968, 1985, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000e9', 'Place & Travel', 'Washington D.C.', 'Served as US senator and Senate Majority Leader in Washington D.C.', 'range', 1985, 2026, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000e9', 'Work & Education', 'University of Kentucky — Law', 'Earned his law degree from the University of Kentucky College of Law in 1967.', 'range', 1964, 1967, '#10b981'),
  ('a0000000-0000-0000-0000-0000000000e9', 'Work & Education', 'US Senator from Kentucky', 'Elected to the Senate in 1984; became the longest-serving Senate Republican leader.', 'range', 1985, 2026, '#10b981'),
  ('a0000000-0000-0000-0000-0000000000e9', 'Relations & Family', 'Married Elaine Chao', 'Married Elaine Chao in 1993; she served as Transportation Secretary under Trump.', 'point', 1993, null, '#ec4899'),
  ('a0000000-0000-0000-0000-0000000000e9', 'Activities', 'Blocked Merrick Garland nomination', 'Refused to hold hearings on Obama''s Supreme Court nominee Merrick Garland in 2016.', 'point', 2016, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-0000000000e9', 'Activities', 'Confirmed three Trump Supreme Court justices', 'Shepherded Gorsuch, Kavanaugh, and Barrett to the Supreme Court.', 'range', 2017, 2020, '#f59e0b'),
  ('a0000000-0000-0000-0000-0000000000e9', 'Health', 'Polio as child', 'Contracted polio at age 2; treatment required extended stays at Warm Springs, Georgia.', 'range', 1944, 1946, '#ef4444');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-0000000000ea', 'Place & Travel', 'Columbus, Indiana', 'Born and raised in Columbus, Indiana in a Catholic family.', 'range', 1959, 1977, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000ea', 'Place & Travel', 'Indianapolis, Indiana', 'Served as Governor of Indiana and built his political career there.', 'range', 2013, 2017, '#3b82f6'),
