INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-0000000000eb', 'Place & Travel', 'Oakland, California', 'Born in Oakland; raised in Berkeley by Indian and Jamaican immigrant parents.', 'range', 1964, 1982, '#3b82f6'),
