  ('a0000000-0000-0000-0000-0000000000fb', 'Place & Travel', 'Paris, France', 'Born in Paris; raised in the 17th arrondissement in an upper-middle-class family.', 'range', 1955, 1973, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000fb', 'Place & Travel', 'Paris / Élysée Palace', 'Built entire career in Paris; lived at the Élysée Palace during presidency.', 'range', 1983, 2026, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000fb', 'Work & Education', 'Sciences Po / ENA', 'Graduated from Sciences Po and the École Nationale d''Administration in 1978.', 'range', 1973, 1978, '#10b981'),
  ('a0000000-0000-0000-0000-0000000000fb', 'Work & Education', 'Mayor of Neuilly-sur-Seine', 'Served as Mayor of Neuilly-sur-Seine 1983–2002; youngest ever when elected.', 'range', 1983, 2002, '#10b981'),
  ('a0000000-0000-0000-0000-0000000000fb', 'Work & Education', 'President of France', 'Served as President 2007–2012; intervened in Libya and hosted the G8 and G20.', 'range', 2007, 2012, '#10b981'),
  ('a0000000-0000-0000-0000-0000000000fb', 'Relations & Family', 'Married Carla Bruni', 'Married supermodel and singer Carla Bruni in February 2008, months into his presidency.', 'point', 2008, null, '#ec4899'),
  ('a0000000-0000-0000-0000-0000000000fb', 'Activities', 'Libya intervention', 'Led the NATO intervention in Libya in 2011 that toppled Muammar Gaddafi.', 'point', 2011, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-0000000000fb', 'Activities', 'Corruption conviction', 'Convicted of corruption and influence-peddling in 2021; sentenced to three years, partially suspended.', 'point', 2021, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-0000000000fb', 'Activities', 'Bygmalion campaign finance scandal', 'Faced trial over illegal financing of his 2012 presidential campaign.', 'range', 2014, 2021, '#f59e0b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-0000000000fc', 'Place & Travel', 'Rouen, France', 'Born in Rouen, Normandy; grew up in a bourgeois family.', 'range', 1954, 1972, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000fc', 'Place & Travel', 'Paris / Élysée Palace', 'Built career at Sciences Po and ENA; served the Socialist Party in Paris.', 'range', 1974, 2026, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000fc', 'Work & Education', 'Sciences Po / ENA', 'Graduated from Sciences Po and ENA 1980; First Secretary of the Socialist Party 1997–2008.', 'range', 1974, 1980, '#10b981'),
  ('a0000000-0000-0000-0000-0000000000fc', 'Work & Education', 'First Secretary of the Socialist Party', 'Led the Socialist Party 1997–2008 during the Jospin government.', 'range', 1997, 2008, '#10b981'),
  ('a0000000-0000-0000-0000-0000000000fc', 'Work & Education', 'President of France', 'Served as President 2012–2017; oversaw Paris attacks and austerity measures.', 'range', 2012, 2017, '#10b981'),
  ('a0000000-0000-0000-0000-0000000000fc', 'Relations & Family', 'Affair with Julie Gayet revealed', 'Affair with actress Julie Gayet exposed by Closer magazine in January 2014.', 'point', 2014, null, '#ec4899'),
  ('a0000000-0000-0000-0000-0000000000fc', 'Activities', 'Paris terrorist attacks', 'Led France''s response to the November 2015 Paris attacks killing 130 people.', 'point', 2015, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-0000000000fc', 'Activities', 'Declined to seek re-election', 'Announced December 2016 he would not seek a second term — first sitting president to do so.', 'point', 2016, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-0000000000fc', 'Health', 'Approval rating collapse', 'Approval ratings fell below 15% — the lowest of any French president in history.', 'range', 2015, 2017, '#ef4444');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-0000000000fd', 'Place & Travel', 'Caetés, Pernambuco, Brazil', 'Born in extreme poverty in rural Pernambuco; moved to São Paulo as a child.', 'range', 1945, 1956, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000fd', 'Place & Travel', 'São Paulo / Brasília', 'Worked in São Paulo steelworks; later served as President in Brasília.', 'range', 1956, 2026, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000fd', 'Work & Education', 'Metalworker — union leader', 'Worked as a lathe operator and rose to lead the steel workers'' union in São Paulo.', 'range', 1960, 1980, '#10b981'),
  ('a0000000-0000-0000-0000-0000000000fd', 'Work & Education', 'Founded Workers'' Party (PT)', 'Co-founded the Partido dos Trabalhadores in 1980; built Brazil''s largest left-wing party.', 'point', 1980, null, '#10b981'),
  ('a0000000-0000-0000-0000-0000000000fd', 'Work & Education', 'President of Brazil — first two terms', 'Served 2003–2011; oversaw Bolsa Família social programme and economic boom.', 'range', 2003, 2011, '#10b981'),
  ('a0000000-0000-0000-0000-0000000000fd', 'Work & Education', 'President of Brazil — third term', 'Returned to the presidency in 2023 after corruption conviction was annulled.', 'range', 2023, 2026, '#10b981'),
  ('a0000000-0000-0000-0000-0000000000fd', 'Relations & Family', 'Married Marisa Letícia', 'Married Marisa Letícia Rocco in 1974; she died of a stroke in 2017.', 'range', 1974, 2017, '#ec4899'),
  ('a0000000-0000-0000-0000-0000000000fd', 'Activities', 'Imprisoned for corruption', 'Jailed in 2018 on corruption charges; released in 2019 after Supreme Court ruling.', 'range', 2018, 2019, '#f59e0b'),
  ('a0000000-0000-0000-0000-0000000000fd', 'Health', 'Lost finger in factory accident', 'Lost the little finger on his left hand in a lathe accident in 1964.', 'point', 1964, null, '#ef4444');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-0000000000fe', 'Place & Travel', 'Glicério, São Paulo, Brazil', 'Born in Glicério; grew up in Rio de Janeiro; made career in the Brazilian Army.', 'range', 1955, 1988, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000fe', 'Place & Travel', 'Brasília / Rio de Janeiro', 'Served as congressman in Brasília; based in Rio; led presidency from Brasília.', 'range', 1991, 2026, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000fe', 'Work & Education', 'Brazilian Army — officer', 'Served in the Brazilian Army 1973–1988; parachute officer; retired as captain.', 'range', 1973, 1988, '#10b981'),
  ('a0000000-0000-0000-0000-0000000000fe', 'Work & Education', 'Federal Deputy — Rio de Janeiro', 'Served in the Chamber of Deputies representing Rio de Janeiro for 27 years.', 'range', 1991, 2019, '#10b981'),
  ('a0000000-0000-0000-0000-0000000000fe', 'Work & Education', 'President of Brazil', 'Served as President 2019–2022; dismantled Amazon protections and disputed 2022 election loss.', 'range', 2019, 2022, '#10b981'),
  ('a0000000-0000-0000-0000-0000000000fe', 'Relations & Family', 'Married Michelle Bolsonaro', 'Married Michelle Bolsonaro in 2007; she played a key role in his 2022 campaign.', 'point', 2007, null, '#ec4899'),
  ('a0000000-0000-0000-0000-0000000000fe', 'Activities', 'Amazon deforestation surge', 'Deforestation in the Brazilian Amazon rose sharply as protections were dismantled.', 'range', 2019, 2022, '#f59e0b'),
  ('a0000000-0000-0000-0000-0000000000fe', 'Activities', 'COVID-19 pandemic denial', 'Called COVID-19 "a little flu"; Brazil suffered one of the world''s highest death tolls.', 'range', 2020, 2022, '#f59e0b'),
  ('a0000000-0000-0000-0000-0000000000fe', 'Health', 'Stabbed during 2018 campaign', 'Was stabbed in the abdomen at a campaign rally in September 2018; nearly fatal.', 'point', 2018, null, '#ef4444');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-000000000100', 'Place & Travel', 'Ottawa / Montreal, Canada', 'Born in Ottawa; raised mostly in Montreal as son of PM Pierre Trudeau.', 'range', 1971, 1994, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000100', 'Place & Travel', 'Ottawa — Prime Minister', 'Served as Prime Minister from 2015; resided at Rideau Cottage in Ottawa.', 'range', 2015, 2025, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000100', 'Work & Education', 'McGill University / UBC', 'BA in literature from McGill; began teaching school after partial MA at UBC.', 'range', 1994, 2002, '#10b981'),
  ('a0000000-0000-0000-0000-000000000100', 'Work & Education', 'Drama and French teacher', 'Taught French and drama in Vancouver and Ottawa before entering politics.', 'range', 2002, 2007, '#10b981'),
  ('a0000000-0000-0000-0000-000000000100', 'Work & Education', 'Prime Minister of Canada', 'Won 2015 election with majority; re-elected in 2019 and 2021 with minorities; resigned 2025.', 'range', 2015, 2025, '#10b981'),
  ('a0000000-0000-0000-0000-000000000100', 'Relations & Family', 'Married Sophie Grégoire', 'Married Sophie Grégoire in 2005; they separated in 2023.', 'range', 2005, 2023, '#ec4899'),
  ('a0000000-0000-0000-0000-000000000100', 'Activities', 'Cannabis legalised in Canada', 'Canada became the first G7 country to federally legalise recreational cannabis in October 2018.', 'point', 2018, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000100', 'Activities', 'Emergencies Act — trucker convoy', 'Invoked the Emergencies Act to end the anti-vaccine-mandate convoy blockade in February 2022.', 'point', 2022, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000100', 'Activities', 'Blackface controversy', 'Photographs emerged of Trudeau in blackface costume from 2001; he apologised publicly.', 'point', 2019, null, '#f59e0b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-000000000102', 'Place & Travel', 'Pyongyang, North Korea', 'Spent his entire adult life in Pyongyang as heir and then ruler of North Korea.', 'range', 1960, 2011, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000102', 'Work & Education', 'Kim Il-sung University', 'Graduated from Kim Il-sung University; studied political economy.', 'range', 1960, 1964, '#10b981'),
  ('a0000000-0000-0000-0000-000000000102', 'Work & Education', 'Korean Workers'' Party leadership', 'Consolidated power within the Korean Workers'' Party from the late 1970s.', 'range', 1980, 1994, '#10b981'),
  ('a0000000-0000-0000-0000-000000000102', 'Work & Education', 'Supreme Leader of North Korea', 'Served as Supreme Leader 1994–2011; developed nuclear weapons program.', 'range', 1994, 2011, '#10b981'),
  ('a0000000-0000-0000-0000-000000000102', 'Activities', 'North Korea''s first nuclear test', 'Oversaw North Korea''s first successful nuclear test on October 9, 2006.', 'point', 2006, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000102', 'Activities', 'Korean famine — Arduous March', 'His military-first policy contributed to a famine killing an estimated 1–3 million people.', 'range', 1994, 1998, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000102', 'Activities', 'Songun — military-first policy', 'Instituted Songun (military-first) politics; poured resources into the armed forces.', 'range', 1995, 2011, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000102', 'Relations & Family', 'Multiple relationships and heirs', 'Had at least three known partners and three confirmed children including Kim Jong-un.', 'range', 1970, 2011, '#ec4899'),
  ('a0000000-0000-0000-0000-000000000102', 'Health', 'Death — heart attack on private train', 'Died December 17, 2011 of a heart attack; aged 69.', 'point', 2011, null, '#ef4444');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-000000000103', 'Place & Travel', 'Mangyongdae, near Pyongyang', 'Born near Pyongyang; spent formative years in Manchuria fighting the Japanese.', 'range', 1912, 1945, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000103', 'Place & Travel', 'Pyongyang — capital of North Korea', 'Ruled from Pyongyang; seldom travelled abroad; built a personality cult around himself.', 'range', 1945, 1994, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000103', 'Work & Education', 'Soviet military training', 'Trained with Soviet Red Army; commissioned as a major; fought with Soviet forces in WWII.', 'range', 1941, 1945, '#10b981'),
  ('a0000000-0000-0000-0000-000000000103', 'Work & Education', 'Founder and Supreme Leader of North Korea', 'Proclaimed the DPRK in 1948; ruled until his death in 1994 through totalitarian control.', 'range', 1948, 1994, '#10b981'),
  ('a0000000-0000-0000-0000-000000000103', 'Activities', 'Korean War launched', 'Ordered the invasion of South Korea on June 25, 1950 starting the Korean War.', 'point', 1950, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000103', 'Activities', 'Juche ideology', 'Developed Juche (self-reliance) ideology as North Korea''s official governing philosophy.', 'range', 1955, 1994, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000103', 'Relations & Family', 'Married Kim Jong-suk', 'Married anti-Japanese guerrilla fighter Kim Jong-suk in 1941; mother of Kim Jong-il.', 'point', 1941, null, '#ec4899'),
  ('a0000000-0000-0000-0000-000000000103', 'Assets', 'Personality cult — statues and monuments', 'Thousands of statues and portraits erected across North Korea; still worshipped after death.', 'range', 1948, 1994, '#14b8a6'),
  ('a0000000-0000-0000-0000-000000000103', 'Health', 'Death — heart failure', 'Died July 8, 1994 of heart failure; preserved at the Kumsusan Palace of the Sun.', 'point', 1994, null, '#ef4444');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-000000000104', 'Place & Travel', 'Barinas, Venezuela', 'Born in Sabaneta, Barinas; grew up in rural poverty in the llanos.', 'range', 1954, 1971, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000104', 'Place & Travel', 'Caracas, Venezuela', 'Led a coup attempt, was imprisoned, then served as President in Caracas.', 'range', 1982, 2013, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000104', 'Work & Education', 'Venezuelan Military Academy', 'Graduated from the Military Academy in 1975; became a paratrooper officer.', 'range', 1971, 1975, '#10b981'),
  ('a0000000-0000-0000-0000-000000000104', 'Work & Education', 'President of Venezuela', 'Served as President 1999–2013; nationalised oil, launched social missions, opposed US influence.', 'range', 1999, 2013, '#10b981'),
  ('a0000000-0000-0000-0000-000000000104', 'Activities', 'Coup attempt — February 1992', 'Led a failed military coup against President Carlos Andrés Pérez; jailed for two years.', 'point', 1992, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000104', 'Activities', 'Survived 2002 coup', 'Briefly ousted in a coup in April 2002; restored to power within 48 hours.', 'point', 2002, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000104', 'Activities', 'Bolivarian Alliance (ALBA) founded', 'Founded the ALBA regional alliance as a socialist alternative to US-led trade agreements.', 'point', 2004, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000104', 'Relations & Family', 'Married Marisabel Rodríguez', 'Second marriage to Marisabel Rodríguez in 1997; divorced 2004.', 'range', 1997, 2004, '#ec4899'),
  ('a0000000-0000-0000-0000-000000000104', 'Health', 'Cancer diagnosis and death', 'Diagnosed with pelvic cancer in 2011; died March 5, 2013 after multiple surgeries in Cuba.', 'range', 2011, 2013, '#ef4444');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-000000000105', 'Place & Travel', 'Caracas, Venezuela', 'Born in Caracas; lifelong career in Venezuelan politics and labour unions.', 'range', 1962, 2026, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000105', 'Work & Education', 'Metro de Caracas — bus driver', 'Worked as a bus driver before becoming a union leader and political figure.', 'range', 1982, 1994, '#10b981'),
  ('a0000000-0000-0000-0000-000000000105', 'Work & Education', 'Foreign Minister of Venezuela', 'Served as Chávez''s Foreign Minister 2006–2012; managed regional diplomacy.', 'range', 2006, 2012, '#10b981'),
  ('a0000000-0000-0000-0000-000000000105', 'Work & Education', 'President of Venezuela', 'Succeeded Chávez as President in 2013; oversaw catastrophic economic collapse.', 'range', 2013, 2026, '#10b981'),
  ('a0000000-0000-0000-0000-000000000105', 'Activities', 'Hyperinflation and economic crisis', 'Venezuela''s inflation exceeded 1,000,000% in 2018; millions fled the country.', 'range', 2015, 2020, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000105', 'Activities', 'Guaidó challenge — 2019', 'Juan Guaidó declared himself president in 2019; backed by 50+ countries but Maduro held power.', 'point', 2019, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000105', 'Activities', 'Disputed 2024 election', 'Claimed victory in the July 2024 election amid widespread fraud allegations.', 'point', 2024, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000105', 'Relations & Family', 'Married Cilia Flores', 'Married National Assembly President Cilia Flores in 2013.', 'point', 2013, null, '#ec4899'),
  ('a0000000-0000-0000-0000-000000000105', 'Activities', 'US sanctions imposed', 'US imposed sweeping sanctions on Venezuela and Maduro personally from 2017.', 'range', 2017, 2026, '#f59e0b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-000000000106', 'Place & Travel', 'Tikrit, Iraq', 'Born near Tikrit; grew up in poverty raised by his uncle after his father disappeared.', 'range', 1937, 1959, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000106', 'Place & Travel', 'Baghdad, Iraq', 'Rose through the Ba''ath Party to seize power in Baghdad; ruled there until capture.', 'range', 1963, 2003, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000106', 'Work & Education', 'Ba''ath Party — rise to power', 'Joined the Ba''ath Party in 1957; became Iraqi President in 1979 after purging rivals.', 'range', 1957, 1979, '#10b981'),
  ('a0000000-0000-0000-0000-000000000106', 'Work & Education', 'President of Iraq', 'Ruled as President 1979–2003; used brutal secret police and chemical weapons against opponents.', 'range', 1979, 2003, '#10b981'),
  ('a0000000-0000-0000-0000-000000000106', 'Activities', 'Iran-Iraq War', 'Launched the Iran-Iraq War in 1980; the conflict lasted 8 years and killed over a million.', 'range', 1980, 1988, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000106', 'Activities', 'Invasion of Kuwait', 'Ordered the invasion of Kuwait in 1990; triggered the Gulf War and international sanctions.', 'point', 1990, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000106', 'Activities', 'Chemical attack on Halabja', 'Ordered a chemical weapons attack on the Kurdish town of Halabja killing up to 5,000.', 'point', 1988, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000106', 'Relations & Family', 'Married Sajida Talfah', 'Married his cousin Sajida Talfah in 1963; they had five children.', 'point', 1963, null, '#ec4899'),
  ('a0000000-0000-0000-0000-000000000106', 'Activities', 'Captured and executed', 'Found hiding in a spider hole near Tikrit in December 2003; executed by hanging in 2006.', 'point', 2003, null, '#f59e0b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-000000000107', 'Place & Travel', 'Sirte, Libya', 'Born in Sirte; grew up in a Bedouin family in the Libyan desert.', 'range', 1942, 1963, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000107', 'Place & Travel', 'Tripoli, Libya', 'Seized power in Tripoli in 1969 coup and ruled Libya from there for 42 years.', 'range', 1969, 2011, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000107', 'Work & Education', 'Libyan Military Academy', 'Graduated from Libyan Military Academy 1965; briefly trained at Beaconsfield, England.', 'range', 1963, 1966, '#10b981'),
  ('a0000000-0000-0000-0000-000000000107', 'Work & Education', 'Leader of Libya', 'Seized power in 1969 coup; ruled via the Jamahiriya "state of the masses" system.', 'range', 1969, 2011, '#10b981'),
  ('a0000000-0000-0000-0000-000000000107', 'Activities', 'Lockerbie bombing — state sponsorship', 'Libyan agents convicted of the 1988 Lockerbie bombing killing 270; Libya later paid reparations.', 'point', 1988, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000107', 'Activities', 'Renounced WMD programme', 'Agreed to dismantle Libya''s WMD programme in 2003 after negotiations with the UK and US.', 'point', 2003, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000107', 'Activities', 'Arab Spring — civil war and death', 'Uprising began February 2011; he was captured and killed by rebels in Sirte, October 2011.', 'range', 2011, 2011, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000107', 'Relations & Family', 'Multiple wives and children', 'Had at least two official wives and several acknowledged children.', 'range', 1970, 2011, '#ec4899'),
  ('a0000000-0000-0000-0000-000000000107', 'Assets', 'Bedouin tent at foreign summits', 'Famously brought his own Bedouin tent to foreign visits including the UN in New York.', 'range', 2000, 2010, '#14b8a6');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-000000000108', 'Place & Travel', 'Kafr-El Meselha, Egypt', 'Born in the Nile Delta; rose through the Egyptian Air Force ranks.', 'range', 1928, 1950, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000108', 'Place & Travel', 'Cairo, Egypt', 'Spent entire political career in Cairo; ruled Egypt from the presidential palace.', 'range', 1975, 2011, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000108', 'Work & Education', 'Egyptian Military Academy / Air Force', 'Graduated from Military Academy 1949; trained as a pilot; rose to Air Force Chief.', 'range', 1949, 1972, '#10b981'),
  ('a0000000-0000-0000-0000-000000000108', 'Work & Education', 'President of Egypt', 'Served as President 1981–2011; maintained peace with Israel; received massive US aid.', 'range', 1981, 2011, '#10b981'),
  ('a0000000-0000-0000-0000-000000000108', 'Activities', 'Peace with Israel maintained', 'Continued Sadat''s peace with Israel throughout his 30-year rule.', 'range', 1981, 2011, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000108', 'Activities', 'Arab Spring — ousted', 'Mass protests in Tahrir Square led to his resignation on February 11, 2011.', 'point', 2011, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000108', 'Activities', 'Trial and acquittal', 'Tried for ordering killing of protesters; initially sentenced to life; acquitted in 2017.', 'range', 2011, 2017, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000108', 'Relations & Family', 'Married Suzanne Thabet', 'Married Suzanne Thabet in 1958; she was known for literacy and children''s rights advocacy.', 'point', 1958, null, '#ec4899'),
  ('a0000000-0000-0000-0000-000000000108', 'Health', 'Death in detention', 'Died February 25, 2020 aged 91 while under house arrest from organ failure.', 'point', 2020, null, '#ef4444');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-00000000010b', 'Place & Travel', 'Ploñsk, Russian Empire (now Poland)', 'Born David Grün in Ploñsk; immigrated to Ottoman Palestine in 1906.', 'range', 1886, 1906, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000010b', 'Place & Travel', 'Tel Aviv / Jerusalem, Israel', 'Led the Zionist project from Tel Aviv; declared Israeli independence in 1948.', 'range', 1906, 1973, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000010b', 'Work & Education', 'Zionist labour movement leadership', 'Led the Histadrut and Jewish Agency, building state institutions before 1948.', 'range', 1920, 1948, '#10b981'),
  ('a0000000-0000-0000-0000-00000000010b', 'Work & Education', 'First Prime Minister of Israel', 'Declared Israeli independence May 14, 1948; served as PM 1948–1953 and 1955–1963.', 'range', 1948, 1963, '#10b981'),
  ('a0000000-0000-0000-0000-00000000010b', 'Activities', 'Declaration of Israeli Independence', 'Read the Declaration of Independence of Israel on May 14, 1948 in Tel Aviv.', 'point', 1948, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-00000000010b', 'Activities', '1948 Arab-Israeli War', 'Led Israel''s defence during the 1948 war; accepted UN ceasefire terms.', 'range', 1948, 1949, '#f59e0b'),
  ('a0000000-0000-0000-0000-00000000010b', 'Activities', 'Reparations agreement with West Germany', 'Negotiated a controversial reparations agreement with West Germany in 1952.', 'point', 1952, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-00000000010b', 'Relations & Family', 'Married Paula Munweis', 'Married Paula Munweis in 1917; they had three children.', 'point', 1917, null, '#ec4899'),
  ('a0000000-0000-0000-0000-00000000010b', 'Place & Travel', 'Retired to Sde Boker kibbutz', 'Moved to the remote Negev kibbutz of Sde Boker after resignation; promoted pioneering spirit.', 'range', 1953, 1973, '#3b82f6');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-00000000010c', 'Place & Travel', 'Predappio, Forlì, Italy', 'Born in Predappio; grew up in the Romagna region of northern Italy.', 'range', 1883, 1902, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000010c', 'Place & Travel', 'Milan / Rome, Italy', 'Founded fascism in Milan; ruled Italy from Rome as Il Duce.', 'range', 1912, 1945, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000010c', 'Work & Education', 'Journalist — Avanti! and Il Popolo d''Italia', 'Edited the socialist Avanti! before founding his own nationalist paper Il Popolo d''Italia.', 'range', 1912, 1922, '#10b981'),
  ('a0000000-0000-0000-0000-00000000010c', 'Work & Education', 'Prime Minister and Duce of Italy', 'PM from 1922; became dictator by 1925; allied with Hitler in WWII.', 'range', 1922, 1943, '#10b981'),
  ('a0000000-0000-0000-0000-00000000010c', 'Activities', 'March on Rome', 'Led the Fascist March on Rome in October 1922; King Victor Emmanuel III appointed him PM.', 'point', 1922, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-00000000010c', 'Activities', 'Invasion of Ethiopia', 'Ordered the Italian invasion of Ethiopia in 1935; used chemical weapons against civilians.', 'range', 1935, 1936, '#f59e0b'),
  ('a0000000-0000-0000-0000-00000000010c', 'Activities', 'Pact of Steel with Hitler', 'Signed the Pact of Steel with Nazi Germany in 1939; entered WWII in June 1940.', 'point', 1939, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-00000000010c', 'Relations & Family', 'Married Rachele Guidi', 'Married Rachele Guidi in 1915; also had a long affair with Clara Petacci.', 'point', 1915, null, '#ec4899'),
  ('a0000000-0000-0000-0000-00000000010c', 'Health', 'Executed by partisans', 'Captured and shot by Italian partisans on April 28, 1945; body hung upside down in Milan.', 'point', 1945, null, '#ef4444');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-00000000010d', 'Place & Travel', 'Prek Sbauv, Cambodia', 'Born Saloth Sar in Prek Sbauv; studied in Paris before returning to lead the Khmer Rouge.', 'range', 1925, 1960, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000010d', 'Place & Travel', 'Phnom Penh / jungle bases, Cambodia', 'Led Khmer Rouge from the jungle; briefly ruled Phnom Penh 1975–1979 before fleeing.', 'range', 1960, 1998, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000010d', 'Work & Education', 'Paris — studied radio electronics', 'Studied in Paris on a scholarship; failed exams; immersed in communist ideology instead.', 'range', 1949, 1953, '#10b981'),
  ('a0000000-0000-0000-0000-00000000010d', 'Work & Education', 'Leader of the Khmer Rouge', 'Led the Khmer Rouge communist guerrilla movement to power in Cambodia in 1975.', 'range', 1963, 1979, '#10b981'),
  ('a0000000-0000-0000-0000-00000000010d', 'Activities', 'Cambodian genocide', 'Ordered evacuation of Phnom Penh and execution of intellectuals; 1.5–2 million died.', 'range', 1975, 1979, '#f59e0b'),
  ('a0000000-0000-0000-0000-00000000010d', 'Activities', 'Fled after Vietnamese invasion', 'Vietnamese forces ousted the Khmer Rouge in January 1979; Pol Pot fled to the jungle.', 'point', 1979, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-00000000010d', 'Activities', 'Placed under house arrest by own movement', 'Placed under house arrest by the Khmer Rouge in 1997; died before facing international justice.', 'point', 1997, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-00000000010d', 'Relations & Family', 'Married Khieu Ponnary', 'Married Khieu Ponnary in 1956; she later suffered severe mental illness.', 'point', 1956, null, '#ec4899'),
  ('a0000000-0000-0000-0000-00000000010d', 'Health', 'Death — disputed causes', 'Died April 15, 1998 of apparent heart failure; some suspected suicide; never tried.', 'point', 1998, null, '#ef4444');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-00000000010e', 'Place & Travel', 'Koboko, Uganda', 'Born in the West Nile region; joined the King''s African Rifles as a young man.', 'range', 1925, 1946, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000010e', 'Place & Travel', 'Kampala, Uganda', 'Seized power in a 1971 coup; ruled from Kampala until overthrow in 1979.', 'range', 1971, 1979, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000010e', 'Place & Travel', 'Jeddah, Saudi Arabia (exile)', 'Fled Uganda in 1979; lived in exile in Saudi Arabia until his death.', 'range', 1979, 2003, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000010e', 'Work & Education', 'British colonial army — King''s African Rifles', 'Rose from private to the highest rank allowed for Black soldiers under British rule.', 'range', 1946, 1962, '#10b981'),
  ('a0000000-0000-0000-0000-00000000010e', 'Work & Education', 'President of Uganda', 'Served as President 1971–1979; his regime killed an estimated 100,000–500,000 Ugandans.', 'range', 1971, 1979, '#10b981'),
  ('a0000000-0000-0000-0000-00000000010e', 'Activities', 'Expulsion of Ugandan Asians', 'Expelled 50,000 South Asian Ugandans in 1972; destroyed the economy.', 'point', 1972, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-00000000010e', 'Activities', 'Entebbe hijacking response', 'Allowed Palestinian hijackers to use Entebbe airport; Israeli commandos rescued the hostages.', 'point', 1976, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-00000000010e', 'Relations & Family', 'Multiple wives and many children', 'Had at least five official wives and over 40 claimed children.', 'range', 1966, 1979, '#ec4899'),
  ('a0000000-0000-0000-0000-00000000010e', 'Health', 'Death in exile', 'Died August 16, 2003 in Jeddah of multiple organ failure; never faced justice.', 'point', 2003, null, '#ef4444');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-00000000010f', 'Place & Travel', 'Kutama, Zvimba, Zimbabwe', 'Born in the Kutama Mission; educated by Jesuit priests in Southern Rhodesia.', 'range', 1924, 1955, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000010f', 'Place & Travel', 'Harare (Salisbury), Zimbabwe', 'Served as PM then President in Harare; held power for 37 years.', 'range', 1980, 2019, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000010f', 'Work & Education', 'Fort Hare University / prison education', 'Graduated from Fort Hare; earned multiple degrees including law while imprisoned.', 'range', 1949, 1963, '#10b981'),
  ('a0000000-0000-0000-0000-00000000010f', 'Work & Education', 'PM then President of Zimbabwe', 'Led Zimbabwe from independence in 1980 until forced to resign in November 2017.', 'range', 1980, 2017, '#10b981'),
  ('a0000000-0000-0000-0000-00000000010f', 'Activities', 'Land redistribution programme', 'Oversaw violent seizure of white-owned farms from 2000; triggered hyperinflation and famine.', 'range', 2000, 2008, '#f59e0b'),
  ('a0000000-0000-0000-0000-00000000010f', 'Activities', 'Gukurahundi massacres', 'His Fifth Brigade massacred an estimated 20,000 Ndebele civilians 1983–1987.', 'range', 1983, 1987, '#f59e0b'),
  ('a0000000-0000-0000-0000-00000000010f', 'Activities', 'Military coup — forced to resign', 'The military placed him under house arrest in November 2017; he resigned after 37 years.', 'point', 2017, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-00000000010f', 'Relations & Family', 'Married Grace Marufu', 'Second marriage to Grace Marufu in 1996; she accumulated vast wealth and sought to succeed him.', 'point', 1996, null, '#ec4899'),
  ('a0000000-0000-0000-0000-00000000010f', 'Health', 'Death in Singapore hospital', 'Died September 6, 2019 in a Singapore hospital receiving ongoing treatment.', 'point', 2019, null, '#ef4444');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-000000000110', 'Place & Travel', 'Valparaíso, Chile', 'Born in Valparaíso into a military family; career took him across Chile and Europe.', 'range', 1915, 1946, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000110', 'Place & Travel', 'Santiago, Chile', 'Led the 1973 coup from Santiago; ruled Chile as military dictator from the capital.', 'range', 1973, 1990, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000110', 'Place & Travel', 'London — arrested', 'Arrested in London in 1998 while receiving medical treatment; detained for 503 days.', 'range', 1998, 2000, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000110', 'Work & Education', 'Chilean Military Academy', 'Career officer; rose to Commander-in-Chief of the Army.', 'range', 1933, 1973, '#10b981'),
  ('a0000000-0000-0000-0000-000000000110', 'Work & Education', 'Head of Military Junta / President of Chile', 'Led the coup against Allende; ruled Chile 1973–1990; implemented free-market reforms.', 'range', 1973, 1990, '#10b981'),
  ('a0000000-0000-0000-0000-000000000110', 'Activities', '1973 coup against Allende', 'Led the US-backed coup on September 11, 1973 overthrowing democratically-elected Allende.', 'point', 1973, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000110', 'Activities', 'Operation Condor', 'Coordinated with other South American dictatorships to hunt and kill political opponents abroad.', 'range', 1975, 1983, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000110', 'Relations & Family', 'Married Lucía Hiriart', 'Married Lucía Hiriart Rodríguez in 1943; she fiercely defended his legacy.', 'point', 1943, null, '#ec4899'),
  ('a0000000-0000-0000-0000-000000000110', 'Health', 'Death before trial', 'Died December 10, 2006 of heart failure before facing criminal charges; aged 91.', 'point', 2006, null, '#ef4444');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-000000000111', 'Place & Travel', 'Ferrol, Galicia, Spain', 'Born in Ferrol; family had a strong military tradition.', 'range', 1892, 1910, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000111', 'Place & Travel', 'Spanish Morocco / Africa', 'Served in Morocco; earned a reputation as a ruthless commander of the Spanish Legion.', 'range', 1912, 1936, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000111', 'Place & Travel', 'Madrid, Spain', 'Ruled Spain as dictator from Madrid''s El Pardo palace from 1939 until his death.', 'range', 1939, 1975, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000111', 'Work & Education', 'Toledo Military Academy', 'Graduated from the Infantry Academy in Toledo in 1910; youngest general in Spain at 33.', 'range', 1907, 1910, '#10b981'),
  ('a0000000-0000-0000-0000-000000000111', 'Work & Education', 'Caudillo of Spain', 'Ruled Spain from 1939 until his death in 1975 as head of state and government.', 'range', 1939, 1975, '#10b981'),
  ('a0000000-0000-0000-0000-000000000111', 'Activities', 'Spanish Civil War — Nationalist victory', 'Led the Nationalist uprising from July 1936; won the Civil War by April 1939.', 'range', 1936, 1939, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000111', 'Activities', 'Stayed neutral in WWII', 'Resisted Hitler''s pressure to join WWII despite debts to Germany and Italy.', 'range', 1939, 1945, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000111', 'Relations & Family', 'Married Carmen Polo', 'Married Carmen Polo y Martínez-Valdés in 1923; she was a prominent social figure.', 'point', 1923, null, '#ec4899'),
  ('a0000000-0000-0000-0000-000000000111', 'Health', 'Death — Parkinson''s and organ failure', 'Died November 20, 1975 after months of deteriorating health; designated Juan Carlos I as successor.', 'point', 1975, null, '#ef4444');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-000000000112', 'Place & Travel', 'Grand Chute, Wisconsin', 'Born near Appleton, Wisconsin; spent his career representing Wisconsin in Washington.', 'range', 1908, 1957, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000112', 'Work & Education', 'Marquette University Law School', 'Graduated from Marquette University Law School in 1935.', 'range', 1930, 1935, '#10b981'),
  ('a0000000-0000-0000-0000-000000000112', 'Work & Education', 'US Marine Corps — WWII', 'Served in the Marines as an intelligence officer; flew combat missions in the Pacific.', 'range', 1942, 1945, '#10b981'),
  ('a0000000-0000-0000-0000-000000000112', 'Work & Education', 'US Senator from Wisconsin', 'Elected to the Senate in 1946; chaired the Permanent Subcommittee on Investigations.', 'range', 1947, 1957, '#10b981'),
  ('a0000000-0000-0000-0000-000000000112', 'Activities', 'McCarthyism — Red Scare investigations', 'Led sweeping investigations into alleged Communist infiltration of the US government 1950–1954.', 'range', 1950, 1954, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000112', 'Activities', 'Army-McCarthy Hearings', 'His televised 1954 Senate hearings exposed his tactics; attorney Welch asked "Have you no decency?"', 'point', 1954, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000112', 'Activities', 'Senate censure', 'Censured by the US Senate in December 1954; his influence collapsed rapidly thereafter.', 'point', 1954, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000112', 'Relations & Family', 'Married Jean Kerr', 'Married his research assistant Jean Kerr in 1953; they adopted a daughter.', 'point', 1953, null, '#ec4899'),
  ('a0000000-0000-0000-0000-000000000112', 'Health', 'Death from alcoholism', 'Died May 2, 1957 of hepatitis related to alcoholism; aged 48.', 'point', 1957, null, '#ef4444');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-000000000113', 'Place & Travel', 'Samarra, Iraq', 'Born Ibrahim Awad Ibrahim al-Badri in Samarra; grew up in a religious household.', 'range', 1971, 1996, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000113', 'Place & Travel', 'Iraq / Syria — ISIS territory', 'Led ISIS across Iraq and Syria; declared the caliphate from Mosul in 2014.', 'range', 2010, 2019, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000113', 'Work & Education', 'Islamic University of Baghdad', 'Earned a PhD in Islamic studies from the Islamic University of Baghdad.', 'range', 1996, 2007, '#10b981'),
  ('a0000000-0000-0000-0000-000000000113', 'Work & Education', 'ISIS Caliph', 'Declared himself Caliph of the Islamic State in June 2014 from the Great Mosque of al-Nuri.', 'range', 2014, 2019, '#10b981'),
  ('a0000000-0000-0000-0000-000000000113', 'Activities', 'ISIS caliphate declared', 'Proclaimed the Islamic State caliphate spanning Iraq and Syria in June 2014.', 'point', 2014, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000113', 'Activities', 'Yazidi genocide', 'Ordered the enslavement and massacre of Yazidis in the Sinjar region of Iraq in 2014.', 'point', 2014, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000113', 'Activities', 'Detained at Camp Bucca', 'Detained by US forces at Camp Bucca in Iraq 2004–2009; met future ISIS commanders there.', 'range', 2004, 2009, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000113', 'Activities', 'ISIS territorial collapse', 'The caliphate lost nearly all territory by 2018–2019 under US-led coalition pressure.', 'range', 2017, 2019, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000113', 'Health', 'Death — US special forces raid', 'Killed himself with a suicide vest during a US Delta Force raid in Barisha, Syria, October 2019.', 'point', 2019, null, '#ef4444');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-000000000114', 'Place & Travel', 'Cincinnati, Ohio', 'Born Charles Milles Maddox in Cincinnati; largely raised in reform schools across the US.', 'range', 1934, 1955, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000114', 'Place & Travel', 'Los Angeles, California', 'Settled in the Haight-Ashbury area; formed the Manson Family commune near Los Angeles.', 'range', 1967, 1969, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000114', 'Place & Travel', 'California State Prison system', 'Spent the majority of his adult life incarcerated in California prisons.', 'range', 1969, 2017, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000114', 'Work & Education', 'Lifelong criminal record', 'First arrested at 13; spent most of his pre-commune years in prison for theft and fraud.', 'range', 1947, 1967, '#10b981'),
  ('a0000000-0000-0000-0000-000000000114', 'Activities', 'Tate-LaBianca murders', 'Directed his "Family" to carry out the Tate-LaBianca murders in August 1969; 9 victims.', 'point', 1969, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000114', 'Activities', 'Death sentence commuted to life', 'Convicted in 1971; death sentence commuted when California briefly abolished the death penalty.', 'point', 1971, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000114', 'Relations & Family', 'Manson Family commune', 'Gathered a devoted group of followers — the "Family" — at Spahn Ranch near Los Angeles.', 'range', 1967, 1969, '#ec4899'),
  ('a0000000-0000-0000-0000-000000000114', 'Items', 'Swastika tattoo on forehead', 'Carved a swastika into his own forehead during his 1970 trial; became one of his most recognised images.', 'point', 1970, null, '#64748b'),
  ('a0000000-0000-0000-0000-000000000114', 'Health', 'Death — colon cancer', 'Died November 19, 2017 of colon cancer while incarcerated at Corcoran State Prison; aged 83.', 'point', 2017, null, '#ef4444');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-000000000115', 'Place & Travel', 'Burlington, Vermont', 'Born in Burlington; grew up in Washington state and attended university in Utah.', 'range', 1946, 1968, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000115', 'Place & Travel', 'Pacific Northwest / Utah / Colorado', 'Committed murders across Washington, Oregon, Utah, and Colorado.', 'range', 1974, 1978, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000115', 'Place & Travel', 'Florida — final murders and execution', 'Committed final murders in Tallahassee; tried and executed in Starke, Florida.', 'range', 1978, 1989, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000115', 'Work & Education', 'University of Washington / law school', 'Studied psychology; briefly enrolled in law school in Utah.', 'range', 1966, 1972, '#10b981'),
  ('a0000000-0000-0000-0000-000000000115', 'Activities', 'Murder spree — at least 30 victims', 'Confessed to 30 murders of young women across 7 states between 1974 and 1978.', 'range', 1974, 1978, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000115', 'Activities', 'Escaped custody twice', 'Escaped from jail in Colorado twice in 1977; used escapes to continue killing.', 'point', 1977, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000115', 'Activities', 'Represented himself at Florida trial', 'Acted as his own lawyer at his 1979 Florida murder trial; convicted and sentenced to death.', 'point', 1979, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000115', 'Work & Education', 'Republican Party volunteer', 'Worked as a volunteer for the Washington Republican Party while committing murders.', 'range', 1972, 1974, '#10b981'),
  ('a0000000-0000-0000-0000-000000000115', 'Health', 'Executed — electric chair', 'Executed by electric chair at Florida State Prison on January 24, 1989; aged 42.', 'point', 1989, null, '#ef4444');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-000000000116', 'Place & Travel', 'Milwaukee, Wisconsin', 'Born in Milwaukee; grew up in Bath Township, Ohio; returned to Milwaukee as an adult.', 'range', 1960, 1978, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000116', 'Place & Travel', 'Milwaukee / Oxford, Wisconsin', 'Committed murders in Milwaukee; buried victims at the Oxford Apartment building.', 'range', 1978, 1991, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000116', 'Work & Education', 'US Army', 'Enlisted in the US Army in 1979; stationed in Germany before being discharged in 1981.', 'range', 1979, 1981, '#10b981'),
