  ('a0000000-0000-0000-0000-000000000116', 'Activities', 'Murders of 17 men and boys', 'Murdered, dismembered, and in some cases consumed 17 victims between 1978 and 1991.', 'range', 1978, 1991, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000116', 'Activities', 'Arrested — Oxford Apartments', 'Arrested July 22, 1991 after apartment revealed human remains; confessed to all murders.', 'point', 1991, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000116', 'Activities', 'Convicted and sentenced to 16 life terms', 'Convicted in 1992; sentenced to 16 consecutive life terms; ineligible for parole.', 'point', 1992, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000116', 'Relations & Family', 'Troubled childhood', 'Parents divorced when he was 18; frequently left alone; showed early signs of antisocial behaviour.', 'range', 1977, 1978, '#ec4899'),
  ('a0000000-0000-0000-0000-000000000116', 'Health', 'Murdered in prison', 'Beaten to death by fellow inmate Christopher Scarver on November 28, 1994 at Columbia Correctional.', 'point', 1994, null, '#ef4444');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-000000000117', 'Place & Travel', 'Queens, New York City', 'Born in Queens; grew up in Laurelton; built his investment business in Manhattan.', 'range', 1938, 1960, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000117', 'Place & Travel', 'Manhattan / Palm Beach, Florida', 'Operated his Ponzi scheme from Manhattan; spent winters at his Palm Beach estate.', 'range', 1960, 2009, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000117', 'Work & Education', 'Hofstra University — economics', 'Studied at Hofstra University; founded Bernard L. Madoff Investment Securities in 1960.', 'range', 1956, 1960, '#10b981'),
  ('a0000000-0000-0000-0000-000000000117', 'Work & Education', 'Bernard L. Madoff Investment Securities', 'Founded and ran his investment firm; served as NASDAQ chairman three times in the 1990s.', 'range', 1960, 2008, '#10b981'),
  ('a0000000-0000-0000-0000-000000000117', 'Activities', 'Ponzi scheme — $65 billion fraud', 'Ran the largest investment fraud in US history; defrauded thousands of investors over four decades.', 'range', 1960, 2008, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000117', 'Activities', 'Arrested and confessed', 'Confessed to his sons in December 2008; arrested December 11, 2008; pled guilty in 2009.', 'point', 2008, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000117', 'Activities', 'Sentenced to 150 years in prison', 'Received a 150-year sentence in June 2009.', 'point', 2009, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000117', 'Relations & Family', 'Married Ruth Alpern', 'Married childhood sweetheart Ruth Alpern in 1959; son Mark committed suicide in 2010.', 'point', 1959, null, '#ec4899'),
  ('a0000000-0000-0000-0000-000000000117', 'Assets', 'Manhattan penthouse and yacht', 'Lived a lavish lifestyle with a Manhattan penthouse, Palm Beach mansion, and multiple yachts.', 'range', 1990, 2008, '#14b8a6'),
  ('a0000000-0000-0000-0000-000000000117', 'Health', 'Death in prison', 'Died April 14, 2021 of renal failure at FMC Butner federal medical facility; aged 82.', 'point', 2021, null, '#ef4444');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-000000000118', 'Place & Travel', 'Flushing, Queens, New York', 'Born in Queens; grew up in Flushing; broke into the film industry in New York and Los Angeles.', 'range', 1952, 1979, '#3b82f6'),
