  ('a0000000-0000-0000-0000-000000000118', 'Activities', 'Convicted of rape and sexual assault', 'Convicted in New York in 2020; sentenced to 23 years; conviction later overturned and retried.', 'point', 2020, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000118', 'Relations & Family', 'Married Georgina Chapman', 'Married fashion designer Georgina Chapman in 2007; she filed for divorce after the scandal.', 'range', 2007, 2017, '#ec4899'),
  ('a0000000-0000-0000-0000-000000000118', 'Assets', 'Oscar-winning film producer', 'Produced or co-produced films winning 81 Academy Awards; known as the "Oscar whisperer."', 'range', 1989, 2017, '#14b8a6');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-000000000119', 'Place & Travel', 'Brooklyn, New York', 'Born in Brooklyn; grew up on the Upper East Side of Manhattan in a wealthy family.', 'range', 1953, 1971, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000119', 'Place & Travel', 'New York / Palm Beach / US Virgin Islands', 'Divided time between Manhattan, Palm Beach mansion, and private Caribbean island.', 'range', 1985, 2019, '#3b82f6'),
