  ('a0000000-0000-0000-0000-000000000119', 'Activities', 'Convicted sex offender — 2008', 'Pled guilty to procuring an underage girl for prostitution in Florida in 2008; served 13 months.', 'point', 2008, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000119', 'Activities', 'Arrested on sex trafficking charges — 2019', 'Arrested in July 2019 on federal sex trafficking charges involving dozens of minors.', 'point', 2019, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000119', 'Relations & Family', 'Association with Ghislaine Maxwell', 'Long-term associate Ghislaine Maxwell allegedly ran his trafficking network; convicted 2021.', 'range', 1994, 2019, '#ec4899'),
