  ('a0000000-0000-0000-0000-000000000119', 'Health', 'Death in federal custody', 'Found dead in his cell at MCC New York on August 10, 2019; ruled suicide; widely disputed.', 'point', 2019, null, '#ef4444');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-00000000011a', 'Place & Travel', 'Rionegro, Antioquia, Colombia', 'Born in Rionegro; grew up in Medellín and surrounding hillside barrios.', 'range', 1949, 1970, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000011a', 'Place & Travel', 'Medellín, Colombia', 'Built and ran the Medellín Cartel from his home city; briefly held in La Catedral prison.', 'range', 1970, 1993, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000011a', 'Work & Education', 'Early criminal career', 'Started with petty theft and car theft before moving into cocaine trafficking in the early 1970s.', 'range', 1968, 1975, '#10b981'),
  ('a0000000-0000-0000-0000-00000000011a', 'Work & Education', 'Medellín Cartel leader', 'Founded and led the Medellín Cartel; at peak supplied 80% of cocaine entering the United States.', 'range', 1976, 1993, '#10b981'),
  ('a0000000-0000-0000-0000-00000000011a', 'Activities', 'Colombian Congressman — elected', 'Elected as an alternate member of the Colombian Congress in 1982; expelled after drug ties exposed.', 'point', 1982, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-00000000011a', 'Activities', 'La Catedral — self-designed prison', 'Surrendered in 1991 to a luxury prison he had built himself; escaped in 1992.', 'range', 1991, 1992, '#f59e0b'),
  ('a0000000-0000-0000-0000-00000000011a', 'Activities', 'Killed by security forces', 'Shot and killed on a Medellín rooftop on December 2, 1993, the day after his 44th birthday.', 'point', 1993, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-00000000011a', 'Relations & Family', 'Married María Victoria Henao', 'Married María Victoria Henao in 1976 when she was 15; they had two children.', 'point', 1976, null, '#ec4899'),
  ('a0000000-0000-0000-0000-00000000011a', 'Assets', 'Hacienda Nápoles estate and zoo', 'Built a massive private estate with a zoo; hippos released after his death still roam Colombia.', 'range', 1978, 1993, '#14b8a6');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-00000000011b', 'Place & Travel', 'La Tuna, Badiraguato, Sinaloa, Mexico', 'Born in the mountains of Sinaloa state; grew up in extreme poverty.', 'range', 1957, 1977, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000011b', 'Place & Travel', 'Sinaloa / US Federal Prison', 'Operated his cartel from Sinaloa; eventually extradited to and imprisoned in the United States.', 'range', 1977, 2026, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000011b', 'Work & Education', 'Sinaloa Cartel — leader', 'Built the Sinaloa Cartel into the world''s largest drug trafficking organisation.', 'range', 1989, 2016, '#10b981'),
  ('a0000000-0000-0000-0000-00000000011b', 'Activities', 'Escaped Puente Grande via laundry cart', 'Escaped from Mexico''s highest-security prison in 2001; reportedly hidden in a laundry cart.', 'point', 2001, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-00000000011b', 'Activities', 'Escaped Altiplano via 1.5 km tunnel', 'Escaped through a tunnel built under his cell shower in 2015; embarrassed the Mexican government.', 'point', 2015, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-00000000011b', 'Activities', 'Extradited to United States', 'Extradited to the US on January 19, 2017; held in isolation at ADX Florence, Colorado.', 'point', 2017, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-00000000011b', 'Activities', 'Convicted and sentenced to life', 'Convicted in the Eastern District of New York in 2019; sentenced to life plus 30 years.', 'point', 2019, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-00000000011b', 'Relations & Family', 'Married Emma Coronel Aispuro', 'Married former beauty queen Emma Coronel Aispuro in 2007; she was later arrested for drug trafficking.', 'point', 2007, null, '#ec4899'),
  ('a0000000-0000-0000-0000-00000000011b', 'Assets', 'Cross-border tunnel network', 'Operated an extensive tunnel network beneath the US-Mexico border for drug smuggling.', 'range', 1990, 2016, '#14b8a6');
